def longestDiverseString(a: int, b: int, c: int) -> str:
    import heapq
    pq = []
    for cnt, ch in [(-a, 'a'), (-b, 'b'), (-c, 'c')]:
        if cnt < 0: heapq.heappush(pq, (cnt, ch))
    res = []
    while pq:
        cnt1, ch1 = heapq.heappop(pq)
        if len(res) >= 2 and res[-1] == res[-2] == ch1:
            if not pq: break
            cnt2, ch2 = heapq.heappop(pq)
            res.append(ch2)
            cnt2 += 1
            if cnt2 < 0: heapq.heappush(pq, (cnt2, ch2))
            heapq.heappush(pq, (cnt1, ch1))
        else:
            res.append(ch1)
            cnt1 += 1
            if cnt1 < 0: heapq.heappush(pq, (cnt1, ch1))
    return "".join(res)

